SET search_path TO pet_resort, public;

-- roles
SELECT setval(pg_get_serial_sequence('pet_resort.roles', 'role_id'), (SELECT MAX(role_id) FROM roles));

-- users
SELECT setval(pg_get_serial_sequence('pet_resort.users', 'user_id'), (SELECT MAX(user_id) FROM users));

